('g3-english-adv-099bf94b6d87', 3, 'english', 'grammar', 'grammar-use-of-english', 'mcq', 4, 'prepositions', 'The cat is ___ the table - you cannot see its head.', null, '["on","under","next to","in front of"]', '{"text":"under","index":1}', 'Không thấy đầu mèo vì nó ở DƯỚI bàn (under). ''On'' là trên mặt bàn - thấy rõ, không phù hợp.', 'Chọn giới từ chỉ vị trí theo ngữ cảnh.', '{"grade":3,"coreTopic":"prepositions","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '65e4df29a16493d6', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-english-adv-447cdde1711b', 3, 'english', 'vocabulary', 'vocabulary-in-context', 'mcq', 4, 'time', '"Half past seven" means ___.', null, '["7:00","7:15","7:30","7:45"]', '{"text":"7:30","index":2}', 'Half past = 30 phút qua giờ → 7:30. Quarter past = 15 phút, quarter to = kém 15.', 'Đọc giờ kém - hơn bằng half/quarter past.', '{"grade":3,"coreTopic":"time","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'b9853f3a5cfe634f', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-english-adv-f321514ae3e8', 3, 'english', 'reading', 'reading', 'true-false', 4, 'mini-read', 'Read the passage. True or False?', null, '["True","False"]', '{"boolean":false}', 'Vé trẻ em là $5, người lớn mới $10. Đổi chỗ giá - bẫy đọc lướt.', 'Đọc hiểu chi tiết số tiền trong thông báo.', '{"grade":3,"coreTopic":"mini-read","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '86e348f34f1f63c8', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', 'The zoo opens at 9 a.m. Tickets cost $5 for children and $10 for adults. The lion show is at 11 a.m.', 'A ticket for a child costs ten dollars.', null),
('g3-english-adv-54c8bcbb80ec', 3, 'english', 'grammar', 'grammar-use-of-english', 'mcq', 4, 'have-got', 'Choose the correct sentence.', null, '["He have got a new bike.","He has got a new bike.","He haves a new bike.","He is have a new bike."]', '{"text":"He has got a new bike.","index":1}', 'Ngôi 3 số ít dùng ''has got'' - ''He has got a new bike.'' ''Have'' đi với I/you/we/they.', 'Dùng have got/has got đúng ngôi.', '{"grade":3,"coreTopic":"have-got","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '9672844515be55a5', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g3-english-adv-1c15abb89e2a', 3, 'english', 'vocabulary', 'vocabulary-in-context', 'mcq', 4, 'places', 'You borrow books here but you must be quiet. Where is it?', null, '["a stadium","a library","a market","a cinema"]', '{"text":"a library","index":1}', 'Thư viện (library) - mượn sách và phải yên tĩnh. Sân vận động, chợ, rạp chiếu phim đều ồn được.', 'Suy luận địa điểm từ hoạt động và quy tắc.', '{"grade":3,"coreTopic":"places","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '043aa2c6f85328a1', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
