('g4-english-adv-54dc7ede9a42', 4, 'english', 'grammar', 'grammar-use-of-english', 'mcq', 5, 'some-any', 'There isn''t ___ milk in the fridge. Can you buy ___?', null, '["some - any","any - some","any - any","some - some"]', '{"text":"any - some","index":1}', 'Câu phủ định dùng ''any''; câu đề nghị lịch sự (Can you...) dùng ''some''. Quy tắc nâng cao của some/any.', 'Phân biệt some/any trong câu phủ định và đề nghị.', '{"grade":4,"coreTopic":"some-any","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '22a9fcc563ab6626', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
