('g5-english-adv-bfd180bb2deb', 5, 'english', 'grammar', 'grammar-use-of-english', 'mcq', 4, 'future', 'A: "What ___ you do this weekend?"  B: "I will visit my uncle."', null, '["do","will","did","are"]', '{"text":"will","index":1}', 'Đáp án dùng ''will visit'' → câu hỏi cũng dùng will: ''What will you do...?''', 'Hỏi đáp thì tương lai với will.', '{"grade":5,"coreTopic":"future","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'b51163b7df7a6111', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g5-english-adv-1aac7a89d31f', 5, 'english', 'vocabulary', 'vocabulary-in-context', 'mcq', 4, 'health', 'You should see a dentist when you have a ___.', null, '["headache","toothache","stomachache","backache"]', '{"text":"toothache","index":1}', 'Đau răng (toothache) → nha sĩ (dentist). Đau đầu, đau bụng, đau lưng gặp bác sĩ khác.', 'Ghép bệnh với chuyên khoa đúng.', '{"grade":5,"coreTopic":"health","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '80fce64802cb11f7', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g5-english-adv-1b241f9bdba0', 5, 'english', 'reading', 'reading', 'true-false', 4, 'mini-read', 'Read the passage. True or False?', null, '["True","False"]', '{"boolean":false}', 'Bài nói ''over many centuries'' - nhiều THẾ KỶ, không phải 1 năm. Chi tiết thời gian là bẫy.', 'Đọc hiểu văn bản thông tin lịch sử.', '{"grade":5,"coreTopic":"mini-read","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'a8c3cbc46e730d89', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', 'The Great Wall of China is more than 21,000 km long. It was built over many centuries to protect the country. Today, millions of tourists visit it every year.', 'The Great Wall was built in one year.', null),
('g5-english-adv-d211cc3a812d', 5, 'english', 'grammar', 'grammar-use-of-english', 'mcq', 5, 'pronouns', 'Minh and I are friends. ___ often play badminton together.', null, '["He","They","We","Us"]', '{"text":"We","index":2}', '''Minh and I'' = chúng tôi → chủ ngữ We. ''Us'' là tân ngữ, không đứng đầu câu.', 'Chọn đại từ chủ ngữ thay cụm người.', '{"grade":5,"coreTopic":"pronouns","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '650fe416414007c3', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
