('g2-english-adv-8ad03a4c6791', 2, 'english', 'vocabulary', 'vocabulary-in-context', 'mcq', 5, 'weather', 'You need an umbrella and boots today. What is the weather like?', null, '["It is sunny.","It is rainy.","It is snowy.","It is cloudy."]', '{"text":"It is rainy.","index":1}', 'Ô + ủng → trời MƯA (rainy). Tuyết cần áo ấm hơn là ô.', 'Suy luận thời tiết từ đồ dùng cần mang.', '{"grade":2,"coreTopic":"weather","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'd4153a0ffc50a4cb', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
