('g2-english-adv-2a2af3cb4717', 2, 'english', 'vocabulary', 'vocabulary-in-context', 'mcq', 5, 'jobs', 'She works in a hospital and helps sick children. She is a ___.', null, '["teacher","farmer","doctor","driver"]', '{"text":"doctor","index":2}', 'Bệnh viện + giúp trẻ ốm → bác sĩ (doctor). 2 manh mối khớp nhau.', 'Đoán nghề nghiệp từ nơi làm việc và công việc.', '{"grade":2,"coreTopic":"jobs","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '331cf44d2d905fbe', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g2-english-adv-5d19abd6a68e', 2, 'english', 'communication', 'functional-language', 'mcq', 5, 'requests', 'The window is open and you are cold. What do you say politely?', null, '["Close it now!","Can you close the window, please?","I want window closed.","Why window open?"]', '{"text":"Can you close the window, please?","index":1}', '''Can you..., please?'' - cách nhờ lịch sự. Câu đầu sai phép lịch sự, hai câu sau sai ngữ pháp.', 'Nhờ người khác lịch sự với Can you...please.', '{"grade":2,"coreTopic":"requests","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '674979a9271aa8a1', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g2-english-adv-463aa43afaf5', 2, 'english', 'reading', 'reading', 'true-false', 5, 'mini-read', 'Read the passage. True or False?', null, '["True","False"]', '{"boolean":true}', 'Lily thích sô-cô-la, em thích va-ni → vị KHÁC nhau = đúng. Câu này phải đọc hết câu cuối mới biết.', 'Đọc câu cuối để so sánh sở thích hai nhân vật.', '{"grade":2,"coreTopic":"mini-read","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '6732cdd75cc0a465', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', 'Lily is eight. She has a little brother. He is four. They both like ice cream, but Lily likes chocolate and her brother likes vanilla.', 'Lily and her brother like different flavours of ice cream.', null),
('g2-english-adv-4ea463f68e65', 2, 'english', 'grammar', 'grammar-use-of-english', 'mcq', 5, 'possessives', 'That is not my pencil. It is ___. (pointing to Lan)', null, '["her","hers","she","Lan pencil"]', '{"text":"hers","index":1}', 'Đứng một mình sau is cần đại từ sở hữu ''hers'' - ''It is hers''. ''Her'' phải đi kèm danh từ.', 'Dùng đại từ sở hữu hers không kèm danh từ.', '{"grade":2,"coreTopic":"possessives","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'bc58a16e22217a8e', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
