('g2-english-adv-42e177fe9bb3', 2, 'english', 'vocabulary', 'vocabulary-in-context', 'mcq', 4, 'house', 'You keep your clothes in it. It has doors and shelves. What is it?', null, '["a fridge","a wardrobe","a bed","a sofa"]', '{"text":"a wardrobe","index":1}', 'Đựng quần áo + có cửa và ngăn → tủ quần áo (wardrobe). Tủ lạnh đựng thức ăn.', 'Đoán đồ nội thất từ công dụng.', '{"grade":2,"coreTopic":"house","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '64775f06eac06cf1', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
