('g2-english-adv-de08d22bdf91', 2, 'english', 'vocabulary', 'vocabulary-in-context', 'mcq', 5, 'days', 'The day after Tuesday is ___.', null, '["Monday","Wednesday","Thursday","Sunday"]', '{"text":"Wednesday","index":1}', 'Sau thứ Ba (Tuesday) là thứ Tư (Wednesday). The day after = ngày hôm sau.', 'Ngày kế tiếp trong tuần.', '{"grade":2,"coreTopic":"days","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '556ecbf84262f0d3', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g2-english-adv-265b020f57f0', 2, 'english', 'communication', 'functional-language', 'mcq', 4, 'classroom', 'You want to go to the toilet during the lesson. You say: "___"', null, '["I go now!","May I go to the toilet, please?","Toilet!","Give me the toilet."]', '{"text":"May I go to the toilet, please?","index":1}', 'Xin phép trong giờ học: ''May I..., please?'' - lịch sự và đúng ngữ pháp.', 'Xin phép lịch sự với May I.', '{"grade":2,"coreTopic":"classroom","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '0d6800d7293430ec', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g2-english-adv-e5420908f514', 2, 'english', 'reading', 'reading', 'true-false', 4, 'mini-read', 'Read the passage. True or False?', null, '["True","False"]', '{"boolean":false}', 'Bài nói rõ ''does not go to school'' - thứ Bảy không đi học. Đọc phủ định.', 'Đọc kỹ câu phủ định trong bài.', '{"grade":2,"coreTopic":"mini-read","moetSubject":"English","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '865a5f0eb190bf9d', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', 'It is Saturday. Nam does not go to school. He plays football with his dad in the morning and watches a film with his mum in the evening.', 'Nam goes to school on Saturday.', null),
