('g2-math-adv-59de5cc0def0', 2, 'math', 'number', 'number-sense', 'mcq', 4, 'comparison', 'Which number is between 45 and 52?', null, '["44","48","53","60"]', '{"text":"48","index":1}', 'Chỉ có 48 nằm giữa 45 và 52. 44 nhỏ hơn 45; 53 và 60 lớn hơn 52.', 'Xác định số nằm giữa hai số cho trước.', '{"grade":2,"coreTopic":"comparison","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '86fe4a61ecb839be', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g2-math-adv-9cdecd9affc0', 2, 'math', 'number', 'number-operations', 'mcq', 5, 'mixed', 'What is 100 - 45 - 20?', null, '["25","35","45","55"]', '{"text":"35","index":1}', '100 - 45 = 55, rồi 55 - 20 = 35. Phép trừ liên tiếp làm từ trái sang phải.', 'Trừ liên tiếp trong phạm vi 100.', '{"grade":2,"coreTopic":"mixed","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '355ff0b27ef2b465', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g2-math-adv-dfaaa089bb78', 2, 'math', 'problem-solving', 'mathematical-reasoning', 'mcq', 5, 'reasoning', 'I am a number. I am greater than 40 and less than 50. I am an even number. My two digits are the same. What number am I?', null, '["44","45","46","55"]', '{"text":"44","index":0}', '44: giữa 40-50, chẵn, hai chữ số giống nhau. 45 lẻ; 46 chữ số khác nhau; 55 lớn hơn 50.', 'Suy luận số từ nhiều điều kiện kết hợp.', '{"grade":2,"coreTopic":"reasoning","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'f5123f885591b882', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
