('g4-math-adv-05e5fd07656b', 4, 'math', 'number', 'fractions', 'mcq', 4, 'fractions', 'Which fraction is the BIGGEST?', null, '["1/2","1/3","1/4","1/8"]', '{"text":"1/2","index":0}', 'Cùng tử số 1: mẫu càng nhỏ phân số càng LỚN. 1/2 lớn nhất - bẫy kinh điển là nghĩ 1/8 lớn vì 8 lớn.', 'So sánh phân số cùng tử số.', '{"grade":4,"coreTopic":"fractions","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'd16eb05cd5df243b', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g4-math-adv-01086742f24b', 4, 'math', 'number', 'fractions', 'mcq', 4, 'fractions', 'What is 3/4 of 20?', null, '["12","15","16","80"]', '{"text":"15","index":1}', '3/4 của 20 = 20 ÷ 4 x 3 = 5 x 3 = 15. Chia mẫu trước, nhân tử sau.', 'Tính phân số của một số.', '{"grade":4,"coreTopic":"fractions","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '161d254d31a2e339', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g4-math-adv-be9f9af44409', 4, 'math', 'problem-solving', 'problem-solving', 'mcq', 4, 'word-problems', 'A train travels 90 km every hour. How far does it travel in 3 hours and 30 minutes?', null, '["270 km","300 km","315 km","360 km"]', '{"text":"315 km","index":2}', '3 giờ: 90 x 3 = 270 km. Nửa giờ: 90 ÷ 2 = 45 km. Tổng 270 + 45 = 315 km.', 'Tính quãng đường với thời gian lẻ nửa giờ.', '{"grade":4,"coreTopic":"word-problems","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'ac99c060a5ea4555', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g4-math-adv-ea9bff78ef8f', 4, 'math', 'problem-solving', 'mathematical-reasoning', 'mcq', 4, 'reasoning', 'The sum of two numbers is 50. Their difference is 10. What is the bigger number?', null, '["20","25","30","40"]', '{"text":"30","index":2}', 'Hai số là 30 và 20: 30+20=50, 30-20=10. Số lớn là 30. Thử từng đáp án là cách nhanh nhất.', 'Bài toán tổng-hiệu kinh điển.', '{"grade":4,"coreTopic":"reasoning","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'c6d22d68d04983fb', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g4-math-adv-97aa908bc95a', 4, 'math', 'measurement', 'measurement', 'mcq', 4, 'perimeter', 'A rectangle is 12 cm long and 5 cm wide. What is its perimeter?', null, '["17 cm","34 cm","60 cm","120 cm"]', '{"text":"34 cm","index":1}', 'Chu vi = (dài + rộng) x 2 = (12 + 5) x 2 = 34 cm. Nhiễu 60 là DIỆN TÍCH (12x5) - bẫy điển hình.', 'Tính chu vi hình chữ nhật, phân biệt với diện tích.', '{"grade":4,"coreTopic":"perimeter","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '9a10ed0b14d0ddd2', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g4-math-adv-d191a9ef1584', 4, 'math', 'measurement', 'measurement', 'mcq', 4, 'area', 'A square has sides of 9 cm. What is its area?', null, '["18 cm²","36 cm²","81 cm²","90 cm²"]', '{"text":"81 cm²","index":2}', 'Diện tích hình vuông = cạnh x cạnh = 9 x 9 = 81 cm². Nhiễu 36 là chu vi (9x4).', 'Tính diện tích hình vuông.', '{"grade":4,"coreTopic":"area","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '5661f250020ad251', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g4-math-adv-049fa40430d6', 4, 'math', 'number', 'number-sense', 'mcq', 4, 'rounding', 'Round 4,567 to the nearest hundred.', null, '["4,500","4,600","4,570","5,000"]', '{"text":"4,600","index":1}', 'Làm tròn đến trăm: nhìn hàng chục là 6 ≥ 5 nên lên 4,600. Nhiễu 4,570 là làm tròn đến chục.', 'Làm tròn số đến hàng trăm.', '{"grade":4,"coreTopic":"rounding","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', 'e5be556a264b0a9c', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
('g4-math-adv-88b18c7c21a4', 4, 'math', 'data', 'data', 'mcq', 5, 'averages', 'Minh scores 8, 9 and 10 in three quizzes. What is his average score?', null, '["8","9","10","27"]', '{"text":"9","index":1}', 'Trung bình = (8 + 9 + 10) ÷ 3 = 27 ÷ 3 = 9. Nhiễu 27 là tổng, quên chia.', 'Tính trung bình cộng đơn giản.', '{"grade":4,"coreTopic":"averages","moetSubject":"Mathematics","alignmentLevel":"topic-skill","curriculumRole":"extension","primaryFramework":"MOET-2018"}', null, true, null, 'owned-original-generated', 'machine-editorial-reviewed-human-academic-signoff-required', '{"examEligible":false,"mockEligible":true,"practiceEligible":true,"commercialReleaseEligible":true,"requiresHumanApprovalForExam":true,"requiresHumanApprovalForCommercialRelease":false}', '73ff11ae145718b1', '{"kind":"generated-v6","method":"cr59-authored-advanced","provenance":"Hand-authored advanced item; original, not copied from a textbook or competition bank."}', '6.0', null, null, null),
